// crates/domain/order_processor.rs
use std::sync::{Arc, Mutex};

pub async fn process_orders(orders: Vec<Order>) -> Result<Vec<ProcessedOrder>, AppError> {
    let results = Arc::new(Mutex::new(Vec::new()));
    let mut handles = Vec::new();

    for order in orders {
        let results_clone = Arc::clone(&results);
        let handle = tokio::spawn(async move {
            let validated = validate_order(&order)?;
            let priced = price_order(&validated);
            let saved = save_to_db(&priced).await?;
            let mut guard = results_clone.lock().unwrap();
            guard.push(saved);
            Ok(saved)
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.await.map_err(|_| AppError::TaskFailed)??;
    }

    let guard = results.lock().unwrap();
    Ok(guard.clone())
}
